mapper.select:
		select FIN_PRODUCT.FINPROD_ID id, FINPROD_MARKET_ID || ':' || FINPROD_ABBR text
		from FIN_PRODUCT, FIN_PRODUCT_ADD, PTL_PORTFOLIO_AUTHORITY
		where FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
		  and FIN_PRODUCT.FINPROD_TYPE2 = #{finprodTypeProd}
		  and FIN_PRODUCT.PROFIT_TYPE = #{profitType}
		  and FIN_PRODUCT.P_FINPROD_ID IS NULL

		  and FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID

          and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}



			and (FIN_PRODUCT.FINPROD_MARKET_ID like concat(concat('%',#{search}),'%')
    			or FIN_PRODUCT.FINPROD_ABBR like concat(concat('%',#{search}),'%'))


        	  and FIN_PRODUCT.FINPROD_ID = #{initValue}

SELECT E.finprodId as finprodId, E.finprodMarketId as finprodMarketId, E.finprodAbbr as finprodAbbr, E.vdate as vdate, E.saleDepartment as saleDepartment, E.effDate as effDate,
E.yield as yield, E.cashId as cashId, E.isInitial as isInitial, E.sendStatus as sendStatus FROM ( SELECT A.FINPROD_ID as finprodId, A.FINPROD_MARKET_ID as finprodMarketId, A.FINPROD_ABBR as finprodAbbr, A.VDATE as vdate, D.SALE_DEPARTMENT as saleDepartment, C.EFF_DATE as effDate,
C.IS_INITIAL as isInitial, C.YIELD*100 as yield, B.CASH_ID as cashId, INF_FIN_CASH_CALC_RULE.SEND_STATUS as sendStatus FROM FIN_PRODUCT A INNER JOIN PTL_MANAGE_OBJ ON PTL_MANAGE_OBJ.MANAGE_OBJ_ID = A.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId} INNER JOIN FIN_CASH_INFO B ON A.FINPROD_ID = B.FINPROD_ID AND B.CASH_TYPE_1 = #{interest} INNER JOIN FIN_CASH_CALC_RULE C ON B.CASH_ID = C.CASH_ID INNER JOIN FIN_PRODUCT_ADD D ON A.FINPROD_ID = D.FINPROD_ID LEFT JOIN INF_FIN_CASH_CALC_RULE ON C.CASH_ID = INF_FIN_CASH_CALC_RULE.CASH_ID AND C.EFF_DATE = INF_FIN_CASH_CALC_RULE.EFF_DATE WHERE A.P_FINPROD_ID IS NULL AND A.PROFIT_TYPE = #{proEarnings} AND A.FINPROD_TYPE2 = #{financingProduct} AND D.IS_LAY = #{YESORNON} UNION ALL SELECT distinct A.FINPROD_ID as finprodId, A.FINPROD_MARKET_ID as finprodMarketId, A.FINPROD_ABBR as finprodAbbr, A.VDATE as vdate, D.SALE_DEPARTMENT as saleDepartment, R.Eff_Date as effDate,
R.Is_Initial isInitial, NULL as yield, NULL as cashId, NULL as sendStatus FROM FIN_PRODUCT A INNER JOIN PTL_MANAGE_OBJ ON PTL_MANAGE_OBJ.MANAGE_OBJ_ID = A.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId} INNER JOIN FIN_PRODUCT B on A.finprod_id= B.p_finprod_id INNER JOIN FIN_CASH_CALC_RULE R on B.finprod_id= R.finprod_id INNER JOIN FIN_PRODUCT_ADD D ON A.FINPROD_ID = D.FINPROD_ID AND D.IS_LAY = #{YESORNOY} WHERE A.P_FINPROD_ID IS NULL AND A.PROFIT_TYPE = #{proEarnings} AND A.FINPROD_TYPE2 = #{financingProduct} )E
AND (E.finprodId IN
null) or E.finprodId in (
#{item}
)
AND NVL(E.sendStatus, '03') = #{sendStatus,jdbcType=VARCHAR}
ANd E.saleDepartment = #{saleDepartment}
AND to_char(E.RELEASEDATE,'yyyy-MM-dd') >= #{releaseDateStart}
AND to_char(E.RELEASEDATE,'yyyy-MM-dd') <= #{releaseDateEnd}
AND to_char(E.EFFDATE,'yyyy-MM-dd') >= #{effDateStart}
AND to_char(E.EFFDATE,'yyyy-MM-dd') <= #{effDateEnd}

		SELECT
    		FIN_PRODUCT_ADD.IS_LAY isLay,
    		FIN_PRODUCT.PROFIT_TYPE profitType,
    		FIN_PRODUCT.VDATE vdate,
   			FIN_PRODUCT.FINPROD_ABBR finprodAbbr,
   			FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId,
    		FIN_PRODUCT_ADD.SALE_DEPARTMENT saleDepartment,
    		FIN_CASH_INFO.CASH_ID cashId,
    		FIN_PRODUCT_ADD.LAY_TYPE layType
		FROM
    		FIN_PRODUCT
		LEFT JOIN    FIN_PRODUCT_ADD
		ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
		LEFT JOIN FIN_CASH_INFO
		ON  FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID

			AND FIN_PRODUCT.FINPROD_ID = #{finprodId}
			AND FIN_PRODUCT.FINPROD_TYPE2  = #{finprodType2}
			AND FIN_PRODUCT.PROFIT_TYPE=#{profitType}
			AND FIN_PRODUCT_ADD.FINPROD_ID = #{finprodId}
			AND FIN_CASH_INFO.CASH_TYPE_1 = #{interest1}
			AND FIN_CASH_INFO.CASH_TYPE_2 = #{interest2}
			AND FIN_CASH_INFO.BRANCH = #{branch}

SELECT 
	count(*)
FROM FIN_PRODUCT_VALUATION
WHERE
	FINPROD_ID = #{finprodId}
	AND FINPROD_TYPE2 = #{finprodType2}
	 AND to_char(VAL_DATE,'yyyy-MM-dd')  = #{valDate}  
	AND INPUT_TYPE = #{inputType}

SELECT A.FINPROD_ABBR finprodAbbr, A.FINPROD_ID finprodId, B.SALE_DEPARTMENT saleDepartment, NVL2(C.YIELD, C.YIELD * 100, C.YIELD) yield, C.EFF_DATE effDate,
C.REMARK remark FROM FIN_PRODUCT A, FIN_PRODUCT_ADD B, FIN_CASH_CALC_RULE C, FIN_CASH_INFO D WHERE A.FINPROD_ID = B.FINPROD_ID AND A.FINPROD_ID = D.FINPROD_ID AND D.CASH_TYPE_1 = #{cashType1} AND D.CASH_ID = C.CASH_ID AND A.FINPROD_TYPE2 = #{finprodType2} AND A.FINPROD_ID = #{finprodId} AND B.IS_LAY = #{YESORNON} AND to_char(C.EFF_DATE,'yyyy-MM-dd') = #{effDate} UNION ALL
SELECT A.FINPROD_ABBR finprodAbbr, A.FINPROD_ID finprodId, B.SALE_DEPARTMENT saleDepartment, NULL yield, to_date(#{effDate},'yyyy-mm-dd') effDate, '' remark FROM FIN_PRODUCT A, FIN_PRODUCT_ADD B WHERE A.FINPROD_ID = B.FINPROD_ID AND A.FINPROD_TYPE2 = #{finprodType2} AND A.FINPROD_ID = #{finprodId} AND B.IS_LAY = #{YESORNOY}
